import React, { useEffect, useState } from "react";
import { Plus } from "lucide-react";
import api from "../services/api";

export default function SalesOrders() {
  const [data, setData] = useState([]);
  const [open, setOpen] = useState(false);
  const [msg, setMsg] = useState("");

  const [form, setForm] = useState({
    buyerName: "",
    buyerType: "PRIVATE",
    commodity: "",
    quantityKg: "",
    agreedPricePerKg: "",
    saleDate: new Date().toISOString().slice(0, 10)
  });

  // Load sales orders
  const load = async () => {
    try {
      const response = await api.get("/sales-orders");

      console.log(
          "SALES ORDERS API RESPONSE:",
          response.data
      );

      setData(response.data);
    } catch (error) {
      console.error(
          "Sales orders loading error:",
          error
      );

      setData([]);
    }
  };

  // IMPORTANT:
  // Do not write useEffect(load, [])
  useEffect(() => {
    load();
  }, []);

  // Create sales order
  const submit = async (e) => {
    e.preventDefault();

    try {
      await api.post("/sales-orders", {
        ...form,
        quantityKg: Number(form.quantityKg),
        agreedPricePerKg: Number(form.agreedPricePerKg)
      });

      setMsg(
          "Sales order created successfully."
      );

      setOpen(false);

      setForm({
        buyerName: "",
        buyerType: "PRIVATE",
        commodity: "",
        quantityKg: "",
        agreedPricePerKg: "",
        saleDate: new Date().toISOString().slice(0, 10)
      });

      await load();

    } catch (error) {
      console.error(
          "Sales order creation error:",
          error
      );

      setMsg(
          error.response?.data?.message ||
          "Unable to create sales order."
      );
    }
  };

  // Mark payment as received
  const pay = async (id) => {
    try {
      await api.put(
          `/sales-orders/${id}/payment?received=true`
      );

      setMsg(
          "Payment marked as received."
      );

      await load();

    } catch (error) {
      console.error(
          "Payment update error:",
          error
      );

      setMsg(
          error.response?.data?.message ||
          "Unable to update payment."
      );
    }
  };

  return (
      <>
        {/* Page Header */}
        <div className="page-head">

          <div>
          <span className="eyebrow">
            MARKET SALES
          </span>

            <h2>
              Sales Orders
            </h2>

            <p>
              Manage buyer orders and payment status.
            </p>
          </div>

          <button
              className="primary"
              onClick={() => setOpen(true)}
          >
            <Plus size={17} />
            New sale
          </button>

        </div>

        {/* Message */}
        {msg && (
            <div className="toast">
              {msg}
            </div>
        )}

        {/* Sales Orders Table */}
        <div className="panel">

          <table>

            <thead>
            <tr>
              <th>Buyer</th>
              <th>Type</th>
              <th>Commodity</th>
              <th>Quantity</th>
              <th>Price/kg</th>
              <th>Date</th>
              <th>Payment</th>
            </tr>
            </thead>

            <tbody>

            {data.map((s) => (
                <tr key={s.id}>

                  <td>
                    <b>
                      {s.buyerName || "-"}
                    </b>
                  </td>

                  <td>
                    {s.buyerType || "-"}
                  </td>

                  <td>
                    {s.commodity || "-"}
                  </td>

                  <td>
                    {s.quantityKg || 0} kg
                  </td>

                  <td>
                    ₹{s.agreedPricePerKg || 0}
                  </td>

                  <td>
                    {s.saleDate || "-"}
                  </td>

                  <td>

                    {s.paymentReceived ? (

                        <span className="badge success">
                      RECEIVED
                    </span>

                    ) : (

                        <button
                            className="small-btn"
                            onClick={() => pay(s.id)}
                        >
                          Mark received
                        </button>

                    )}

                  </td>

                </tr>
            ))}

            </tbody>

          </table>

          {!data.length && (
              <div className="empty">
                No sales orders found.
              </div>
          )}

        </div>

        {/* New Sales Order Modal */}
        {open && (
            <div className="modal-bg">

              <form
                  className="modal"
                  onSubmit={submit}
              >

                <div className="modal-head">

                  <h3>
                    New Sales Order
                  </h3>

                  <button
                      type="button"
                      onClick={() => setOpen(false)}
                  >
                    ×
                  </button>

                </div>

                <div className="form-grid">

                  {/* Buyer Name */}
                  <label>
                    Buyer name

                    <input
                        required
                        value={form.buyerName}
                        onChange={(e) =>
                            setForm({
                              ...form,
                              buyerName: e.target.value
                            })
                        }
                        placeholder="Enter buyer name"
                    />
                  </label>

                  {/* Buyer Type */}
                  <label>
                    Buyer type

                    <select
                        value={form.buyerType}
                        onChange={(e) =>
                            setForm({
                              ...form,
                              buyerType: e.target.value
                            })
                        }
                    >
                      <option value="PRIVATE">
                        PRIVATE
                      </option>

                      <option value="GOVERNMENT">
                        GOVERNMENT
                      </option>

                      <option value="FPO">
                        FPO
                      </option>
                    </select>

                  </label>

                  {/* Commodity */}
                  <label>
                    Commodity

                    <input
                        required
                        value={form.commodity}
                        onChange={(e) =>
                            setForm({
                              ...form,
                              commodity: e.target.value
                            })
                        }
                        placeholder="Example: Tomato"
                    />
                  </label>

                  {/* Quantity */}
                  <label>
                    Quantity (kg)

                    <input
                        type="number"
                        step="0.01"
                        min="0"
                        required
                        value={form.quantityKg}
                        onChange={(e) =>
                            setForm({
                              ...form,
                              quantityKg: e.target.value
                            })
                        }
                    />
                  </label>

                  {/* Price */}
                  <label>
                    Price per kg

                    <input
                        type="number"
                        step="0.01"
                        min="0"
                        required
                        value={form.agreedPricePerKg}
                        onChange={(e) =>
                            setForm({
                              ...form,
                              agreedPricePerKg:
                              e.target.value
                            })
                        }
                    />
                  </label>

                  {/* Date */}
                  <label>
                    Date

                    <input
                        type="date"
                        required
                        value={form.saleDate}
                        onChange={(e) =>
                            setForm({
                              ...form,
                              saleDate: e.target.value
                            })
                        }
                    />
                  </label>

                </div>

                <button
                    type="submit"
                    className="primary full"
                >
                  Create sales order
                </button>

              </form>

            </div>
        )}
      </>
  );
}
